import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        int mx = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
            mx = Math.max(mx, a[i]);
        }
        // Bucket the request indices by deadline (CSR layout).
        int[] start = new int[mx + 2];
        for (int v : a) start[v + 1]++;
        for (int v = 0; v <= mx; v++) start[v + 1] += start[v];
        int[] fill = Arrays.copyOf(start, mx + 1);
        int[] order = new int[n];
        for (int i = 0; i < n; i++) order[fill[a[i]]++] = i;
        boolean[] alive = new boolean[n];
        Arrays.fill(alive, true);
        int left = 0, count = n, t = 0;
        StringBuilder sb = new StringBuilder();
        while (count > 0) {
            sb.append(count).append(' ');
            while (!alive[left]) left++;
            alive[left] = false; // the head is served this second and leaves
            count--;
            t++;
            if (t <= mx)
                for (int j = start[t]; j < start[t + 1]; j++)
                    if (alive[order[j]]) {
                        alive[order[j]] = false;
                        count--;
                    }
        }
        sb.append('0');
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int, n)
	mx := 0
	for i := range a {
		a[i] = int(nextInt())
		mx = max(mx, a[i])
	}
	// Bucket the request indices by deadline (CSR layout).
	start := make([]int, mx+2)
	for _, v := range a {
		start[v+1]++
	}
	for v := 0; v <= mx; v++ {
		start[v+1] += start[v]
	}
	fill := make([]int, mx+1)
	copy(fill, start)
	order := make([]int, n)
	for i, v := range a {
		order[fill[v]] = i
		fill[v]++
	}
	alive := make([]bool, n)
	for i := range alive {
		alive[i] = true
	}
	left, count, t := 0, n, 0
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for count > 0 {
		w.WriteString(strconv.Itoa(count))
		w.WriteByte(' ')
		for !alive[left] {
			left++
		}
		alive[left] = false // the head is served this second and leaves
		count--
		t++
		if t <= mx {
			for j := start[t]; j < start[t+1]; j++ {
				if alive[order[j]] {
					alive[order[j]] = false
					count--
				}
			}
		}
	}
	w.WriteString("0\n")
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
